117			t.Errorf("D.Parents = %v, want [A B]", got)
118		}
119		if got := graph["E"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
120			t.Errorf("E.Parents = %v, want [A B]", got)
121		}
122	}
