124	// TestRegisterAddIntoListWithSpareCapacity covers adding an edge into a child
125	// list that carries spare capacity: a second record's list may share that
126	// tail storage, so appending into the spare capacity must never overwrite a
127	// name the other record still uses.
128	func TestRegisterAddIntoListWithSpareCapacity(t *testing.T) {
129		// B.Children = [D] with two slots of spare capacity. A.Children aliases
130		// the tail window of the SAME backing array ([Y Z]), so the graph is
131		// consistent but an in-place append into B would overwrite A's names.
132		backing := make([]string, 3, 3)
133		backing[0] = "D"
134		backing[1] = "Y"
135		backing[2] = "Z"
136		b := &Lineage{Dataset: "B", Children: backing[:1]}  // [D], sees the spare capacity
137		a := &Lineage{Dataset: "A", Children: backing[1:3]} // [Y Z], same array
138		c := &Lineage{Dataset: "C", Parents: nil}           // root so far
139		d := &Lineage{Dataset: "D", Parents: []string{"B"}}
140		y := &Lineage{Dataset: "Y", Parents: []string{"A"}}
141		z := &Lineage{Dataset: "Z", Parents: []string{"A"}}
142		graph := map[string]*Lineage{"A": a, "B": b, "C": c, "D": d, "Y": y, "Z": z}
143	
144		// C gains B as its only upstream: B.Children must become [C D] without
145		// touching the [Y Z] names living in B's spare capacity (which A's list
146		// is modeled as owning independently).
147		if err := Register(graph, Dataset{Name: "C"}, []string{"B"}); err != nil {
148			t.Fatalf("Register(C, [B]) unexpected error: %v", err)
149		}
