210			t.Fatalf("Register(C, [A B]) unexpected error: %v", err)
211		}
212		assertLineageConsistent(t, graph)
213		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
214			t.Errorf("A.Children = %v, want [C D]", got)
215		}
216		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
217			t.Errorf("B.Children = %v, want [C D]", got)
218		}
219		if got := graph["D"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
220			t.Errorf("D.Parents = %v, want [A B]", got)
221		}
222		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
223			t.Errorf("C.Parents = %v, want [A B]", got)
224		}
225		// The rebuilt lists are independent storage now.
226		graph["A"].Children = append(graph["A"].Children, "leak")
227		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
228			t.Errorf("B.Children = %v, want [C D] after mutating A's list", got)
229		}
