232	// TestRegisterPreservesOwnDownstreamSharedStorage verifies that the changed
233	// dataset keeps its own downstream even when its child list shares storage
234	// with an unrelated record's list, and that other record is left intact.
235	func TestRegisterPreservesOwnDownstreamSharedStorage(t *testing.T) {
236		// C and X both list child E through the same backing array window.
237		backing := make([]string, 1, 3)
238		backing[0] = "E"
