1	package chainledger
2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// This file pins the single relationship rule shared by graph reads
9	// (UnmarshalGraphFile/ParseSnapshot via lineageFromAdjacency) and batch
10	// applies (ApplyBatch via applyAdjacency): both materialize lineage through
11	// materializeLineage, so every dataset's direct upstreams correspond to those
12	// upstreams' direct downstreams, lists are sorted and duplicate-free, removed
13	// nodes leave no residual edges, and surviving node records keep exposing the
14	// updated relationships through the pointers callers already hold.
15	
16	// assertLineageConsistent checks the parent/child correspondence of every
17	// node: parents are sorted/deduped, every parent lists the node exactly once,
18	// and no child list references a missing dataset or repeats a name.
19	func assertLineageConsistent(t *testing.T, graph map[string]*Lineage) {
20		t.Helper()
21		for name, entry := range graph {
22			if entry == nil {
23				t.Errorf("graph[%q] is nil", name)
24				continue
25			}
26			if got := uniqueSorted(entry.Parents); !reflect.DeepEqual(got, entry.Parents) {
27				t.Errorf("%s.Parents = %v, want sorted and duplicate-free", name, entry.Parents)
28			}
29			if got := uniqueSorted(entry.Children); !reflect.DeepEqual(got, entry.Children) {
30				t.Errorf("%s.Children = %v, want sorted and duplicate-free", name, entry.Children)
31			}
32			for _, parent := range entry.Parents {
33				p, ok := graph[parent]
34				if !ok {
35					t.Errorf("%s lists upstream %q which is absent from the graph", name, parent)
36					continue
37				}
38				count := 0
39				for _, child := range p.Children {
40					if child == name {
41						count++
42					}
43				}
44				if count != 1 {
45					t.Errorf("upstream %q lists downstream %s %d times, want exactly once", parent, name, count)
46				}
47			}
48			for _, child := range entry.Children {
49				c, ok := graph[child]
50				if !ok {
51					t.Errorf("%s lists child %q which is absent from the graph", name, child)
52					continue
53				}
54				found := false
55				for _, parent := range c.Parents {
56					if parent == name {
57						found = true
58					}
59				}
60				if !found {
61					t.Errorf("%s lists child %q, but %s does not list it back as an upstream", name, child, child)
62				}
63			}
64		}
65	}
66	
67	// TestReadGraphMaterializesCorrespondingRelations covers the read side of the
68	// shared rule: after reading a legal graph, A is root, B depends on A, C
69	// depends on B, and D is a separate root — parent and child lists correspond.
70	func TestReadGraphMaterializesCorrespondingRelations(t *testing.T) {
71		data := []byte(`{
72	  "datasets": [
73	    {"name": "A", "upstreams": []},
74	    {"name": "B", "upstreams": ["A"]},
75	    {"name": "C", "upstreams": ["B"]},
76	    {"name": "D", "upstreams": []}
77	  ]
78	}`)
79		graph, err := UnmarshalGraphFile(data)
80		if err != nil {
81			t.Fatalf("UnmarshalGraphFile unexpected error: %v", err)
82		}
83		assertLineageConsistent(t, graph)
84		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"B"}) {
85			t.Errorf("A.Children = %v, want [B]", got)
86		}
87		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"A"}) {
88			t.Errorf("B.Parents = %v, want [A]", got)
89		}
90		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
91			t.Errorf("B.Children = %v, want [C]", got)
92		}
93		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
94			t.Errorf("C.Parents = %v, want [B]", got)
95		}
96		if got := graph["D"].Children; len(got) != 0 {
97			t.Errorf("D.Children = %v, want empty", got)
98		}
99	}
