101	// TestApplyRepointUpstreamsFollowsSharedRule is the headline example: A is
102	// root, B depends on A, C depends on B, plus root D. After replacing B's
103	// upstreams with D, A no longer lists B, D lists B once, B still lists C, and
104	// C still depends on B.
105	func TestApplyRepointUpstreamsFollowsSharedRule(t *testing.T) {
106		graph := buildGraph(t, P("A"), P("D"), P("B", "A"), P("C", "B"))
107		heldB := graph["B"]
108		heldC := graph["C"]
109	
