119			t.Errorf("D.Children = %v, want [B] exactly once", got)
120		}
121		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"D"}) {
122			t.Errorf("B.Parents = %v, want [D]", got)
123		}
